def process(rows, cfg=None):
    out = []
    seen = {}
    cfg = cfg or {}
    for r in rows:
        try:
            uid = int(r.get('user') or r['uid'])
        except Exception:
            continue
        amt = float(r.get('amount', 0)) * (1.2 if r.get('region') == 'EU' else 1)
        if cfg.get('skip_small') and amt < 5:
            continue
        if uid in seen:
            seen[uid]['total'] += amt
            seen[uid]['n'] += 1
        else:
            seen[uid] = {'uid': uid, 'total': amt, 'n': 1}
            out.append(seen[uid])
    for s in out:
        s['avg'] = round(s['total'] / s['n'], 2)
        if s['total'] > cfg.get('vip', 1000):
            s['tier'] = 'vip'
        elif s['total'] > 100:
            s['tier'] = 'regular'
        else:
            s['tier'] = 'new'
    return sorted(out, key=lambda s: -s['total'])
